const read = p => JSON.parse(fs.readFileSync(p, 'utf8'));
const hash = p => crypto.createHash('sha256').update(fs.readFileSync(p)).digest('hex');
const bars = read(`${dir}/_data/bars_indices.json`);
const sectors = read(`${dir}/_data/bars_sectors.json`);
const cryptoBars = read(`${dir}/_data/bars_crypto.json`);
