const claims = [];
let seq = 0;
const escape = s => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
const fr = (v, decimals = 1, suffix = '', sign = false) => {
  const n = Number(v); const text = Math.abs(n).toFixed(decimals).replace('.', ',');
  return `${n < 0 ? '−' : (sign && n >= 0 ? '+' : '')}${text}${suffix}`;
};
function direct(label, artifact, pointer, value, rendered, render, authority) {
  const id = `${label}_${++seq}`;
  const claim = { id, rendered_text: rendered, source_artifact: artifact, source_sha256: hash(artifact), source_pointer: pointer, source_value: value, render };
  if (authority) claim.authority = authority;
  claims.push(claim); return `<span data-claim="${id}">${rendered}</span>`;
}
function pct(label, artifact, pointer, series, now, ago, decimals = 1) {
  const v = (series[now][4] / series[ago][4] - 1) * 100;
  const id = `${label}_${++seq}`; const rendered = fr(v, decimals, ' %', true);
  claims.push({ id, rendered_text: rendered, source_artifact: artifact, source_sha256: hash(artifact), source_pointer: `${pointer}/${now}/4`, source_value: series[now][4], render: { scale: 1, decimals, sign: 'always', suffix: ' %', format: 'fr' }, formula: { operation: 'ratio_pct', numerator_pointer: `${pointer}/${now}/4`, denominator_pointer: `${pointer}/${ago}/4`, result: v } });
  return `<span data-claim="${id}">${rendered}</span>`;
}
function get(data, symbol) { return data.results[0].data.find(x => x.symbol === symbol); }
const ib = s => get(bars, s), sb = s => get(sectors, s), cb = s => get(cryptoBars, s);
