// Corrélation des rendements quotidiens entre deux séries de bars_indices, sur une fenêtre décrite.
// Le gate recalcule la valeur depuis les barres : une affirmation de diversification ne doit pas
// reposer sur un nombre que le lecteur ne peut pas refaire.
const IDXPOS = { SPY: 0, QQQ: 1, IWM: 2, DIA: 3, GLD: 4, SLV: 5, TLT: 6, USO: 7 };
const BARS = `${dir}/_data/bars_indices.json`;
function correl(label, a, b, window = 29) {
  const A = ib(a), B = ib(b);
  const pa = `/results/0/data/${IDXPOS[a]}/bars/${A.bars.length - 1}/4`;
  const pb = `/results/0/data/${IDXPOS[b]}/bars/${B.bars.length - 1}/4`;
  const r = (() => {
    const ra = [], rb = [];
    for (let k = window - 1; k >= 0; k--) {
      const ia = A.bars.length - 1 - k, ibx = B.bars.length - 1 - k;
      ra.push(A.bars[ia][4] / A.bars[ia - 1][4] - 1);
      rb.push(B.bars[ibx][4] / B.bars[ibx - 1][4] - 1);
    }
    const m = v => v.reduce((s, x) => s + x, 0) / v.length;
    const ma = m(ra), mb = m(rb);
    let cov = 0, va = 0, vb = 0;
    for (let i = 0; i < ra.length; i++) { cov += (ra[i] - ma) * (rb[i] - mb); va += (ra[i] - ma) ** 2; vb += (rb[i] - mb) ** 2; }
    return cov / Math.sqrt(va * vb);
  })();
  const id = `${label}_${++seq}`; const rendered = fr(r, 2, '', true);
  claims.push({ id, rendered_text: rendered, source_artifact: BARS, source_sha256: hash(BARS), source_pointer: pa,
    source_value: A.bars.at(-1)[4], render: { scale: 1, decimals: 2, sign: 'always', format: 'fr' },
    formula: { operation: 'pearson_window', numerator_pointer: pa, denominator_pointer: pb, window, result: r } });
  return `<span data-claim="${id}">${rendered}</span>`;
}

