const findBars = (node, symbol) => { if (!node || typeof node !== 'object') return null; if (node.symbol === symbol && Array.isArray(node.bars)) return node; for (const value of Object.values(node)) { const found = findBars(value, symbol); if (found) return found; } return null; };
const blastA = read(`${dir}/_focus/blast_bars_a.json`), blastB = read(`${dir}/_focus/blast_bars_b.json`);
const percent = bar => { const i = baseIndex(bar); return Number(((bar.bars.at(-1)[4] / bar.bars[i][4] - 1) * 100).toFixed(4)); };
