  propagation: [...['MSFT','NVDA','AMZN','GOOGL'].map(x => [x, percent(findBars(blastA, x))]), ...['JPM','XOM','NEM','LEN'].map(x => [x, percent(findBars(blastB, x))])],
  vix: options.items.filter(x => x.type === 'term_structure_point').map(x => [x.tenor, x.level]),
